import{_ as l,a0 as o,w as r,s as d,ao as p,I as i,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 上殺死一個殭屍進程 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上殺死一個殭屍進程 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上殺死一個殭屍進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上殺死一個殭屍進程 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211031 How to kill a zombie process on Linux","title":"如何在 Linux 上殺死一個殭屍進程","tag":"202111","desc":""},"relativePath":"202111/20211031 How to kill a zombie process on Linux.md","filePath":"[post].md"}'),u={name:"202111/20211031 How to kill a zombie process on Linux.md"};function b(m,s,h,k,x,c){const a=o("Link");return r(),d("div",null,[s[18]||(s[18]=p('<h1 id="如何在-linux-上殺死一個殭屍進程" tabindex="-1">如何在 Linux 上殺死一個殭屍進程 <a class="header-anchor" href="#如何在-linux-上殺死一個殭屍進程" aria-label="Permalink to “如何在 Linux 上殺死一個殭屍進程”">​</a></h1><blockquote><p>要殺死一個殭屍進程，你必須從進程列表中刪除其名稱。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/01/095024jyrvo8ss5jnxysqo.jpg" alt=""></p><p>萬聖節快樂！</p><p>這裏有一個和 Unix 紀元一樣古老的故事。自從有了 C 和 Unix，以及（後來的）Linux，我們就有了“<ruby>殭屍<rt>zombie</rt></ruby>”。具體來説，有一些進程被標記為“<ruby>殭屍進程<rt>zombie process</rt></ruby>”。一些人誤解它，另一些人忽視它，而它對我們許多人試圖 “殺死” 這些進程的努力免疫，沒有什麼成效。這是為什麼呢？</p><h3 id="linux-中的進程是什麼" tabindex="-1">Linux 中的進程是什麼？ <a class="header-anchor" href="#linux-中的進程是什麼" aria-label="Permalink to “Linux 中的進程是什麼？”">​</a></h3>',6)),i("p",null,[s[1]||(s[1]=n("這一切始於執行 Linux 中的一個程序時，當它被執行時，它的運行實例被稱為進程。你可以用 ",-1)),e(a,{href:"https://opensource.com/article/21/8/linux-procps-ng"},{default:t(()=>[...s[0]||(s[0]=[n("ps 命令",-1)])]),_:1}),s[2]||(s[2]=n(" 查看你的 Linux 環境中的所有進程：",-1))]),s[19]||(s[19]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ax</span></span>
<span class="line"><span>        PID TTY         STAT   TIME COMMAND</span></span>
<span class="line"><span>        1 ?     Ss      0:01 /usr/lib/systemd/systemd rhgb --switched-root --sys</span></span>
<span class="line"><span>        2 ?     S       0:00 [kthreadd]</span></span>
<span class="line"><span>        3 ?     I&lt;      0:00 [rcu_gp]</span></span>
<span class="line"><span>        4 ?     I&lt;      0:00 [rcu_par_gp]</span></span></code></pre></div><p>有時一個進程啓動另一個進程，使第一個進程成為第二個進程的父進程。<code>pstree</code> 命令是一個很好的工具，可以讓你看到系統中進程的“家譜”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pstree -psn</span></span>
<span class="line"><span>systemd(1)─┬─systemd-journal(952)</span></span>
<span class="line"><span>        ├─systemd-udevd(963)</span></span>
<span class="line"><span>        ├─systemd-oomd(1137)</span></span>
<span class="line"><span>        ├─systemd-resolve(1138)</span></span>
<span class="line"><span>        ├─systemd-userdbd(1139)─┬─systemd-userwor(12707)</span></span>
<span class="line"><span>        │                     ├─systemd-userwor(12714)</span></span>
<span class="line"><span>        │                     └─systemd-userwor(12715)</span></span>
<span class="line"><span>        ├─auditd(1140)───{auditd}(1141)</span></span>
<span class="line"><span>        ├─dbus-broker-lau(1164)───dbus-broker(1165)</span></span>
<span class="line"><span>        ├─avahi-daemon(1166)───avahi-daemon(1196)</span></span>
<span class="line"><span>        ├─bluetoothd(1167)</span></span></code></pre></div><p>每個進程在系統中都會被分配一個編號。進程編號（PID）1 被分配給啓動過程中執行的第一個進程，PID 1 之後的每一個進程都是它的子孫。PID 1 進程是初始化進程，在大多數新版本的 Linux 中，它只是一個指向 <code>systemd</code> 程序的符號鏈接。</p><h3 id="用-kill-命令結束一個進程" tabindex="-1">用 kill 命令結束一個進程 <a class="header-anchor" href="#用-kill-命令結束一個進程" aria-label="Permalink to “用 kill 命令結束一個進程”">​</a></h3><p>你可以用 <code>kill</code> 命令來終止 Linux 系統中的進程。儘管名字叫 “殺死”，但 <code>kill</code> 命令和其他一些命令，如 <code>pkill</code> 和 <code>killall</code>，都是為向一個或多個進程發送信號而編寫/設計的。當沒有指定信號時，它發送的默認信號是 <code>SIGTERM</code> 信號，以終止進程。</p><p>當一個父進程死亡或被殺死，而其子進程沒有跟隨其父進程的死亡，我們稱該進程為“<ruby>孤兒進程<rt>orphan process</rt></ruby>”。</p><h3 id="如何殺死一個殭屍進程" tabindex="-1">如何殺死一個殭屍進程 <a class="header-anchor" href="#如何殺死一個殭屍進程" aria-label="Permalink to “如何殺死一個殭屍進程”">​</a></h3><p>另一方面，殭屍進程是不能被“殺死”的！你可能會問為什麼？因為它們已經死了！</p><p>每一個子進程，當被終止時，都會成為一個殭屍進程，然後被父進程刪除。當進程退出並釋放它所使用的資源時，它的名字仍然在操作系統的進程表中。這時，父進程的工作就是把它的名字從進程表中刪除。如果沒有刪除，我們就有了殭屍進程，它不再是一個真正的進程，而只是操作系統進程表上的一個條目。</p><p>這就是為什麼試圖對一個<ruby>失效的<rt>defunct</rt></ruby>（殭屍）進程執行 “殺死” 命令，即使使用 <code>-9</code>（<code>SIGKILL</code>）選項也不起作用，因為沒有什麼可以殺死的。</p><p>因此，要殺死一個殭屍進程，比如從進程列表（進程表）中刪除其名稱，你必須殺死其父進程。例如，如果 PID 5878 是一個殭屍進程，而它的父進程是 PID 4809，那麼要殺死殭屍進程（5878），就必須結束父進程（4809）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo kill -9 4809  # 4809 是父進程，而非殭屍</span></span></code></pre></div><p>我對殭屍的最後一句警告：在殺死父進程時要非常小心。如果一個進程的父進程是 PID 1，而你殺了它，你就會重新啓動自己！</p><p>而這將是一個更可怕的故事！</p><hr>`,16)),i("p",null,[s[4]||(s[4]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/21/10/linux-zombie-process"},{default:t(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/21/10/linux-zombie-process",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/ansilva"},{default:t(()=>[...s[5]||(s[5]=[n("Anderson Silva",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const T=l(u,[["render",b]]);export{y as __pageData,T as default};
